-- Extracted from MASVINGO.pdf.
-- These are branch Treasurer and Secretary contacts, not prophet assignments.
-- Review the schema and run in Supabase SQL Editor.

create table if not exists public.branch_contacts (
  id text primary key,
  branch_id text,
  branch_name text not null,
  province text not null default 'MASVINGO',
  role text not null,
  name text not null default '',
  phone text not null default '',
  source text not null default ''
);

on conflict (id) do update set
  branch_id = excluded.branch_id,
  branch_name = excluded.branch_name,
  province = excluded.province,
  role = excluded.role,
  name = excluded.name,
  phone = excluded.phone,
  source = excluded.source;
